    def compare_array_of_arrays(arr1, arr2):



        def sort_key_outer(event_array):
            try:
                return event_array[0]['event_id']
            except (IndexError, KeyError, TypeError):
                return None                                              

        def sort_key_inner(competitor_obj):
            try:
                return competitor_obj['competitor_id']
