                return None                              

        arr1_sorted = sorted([sorted(inner_arr, key=sort_key_inner) for inner_arr in arr1 if inner_arr], key=sort_key_outer)
        arr2_sorted = sorted([sorted(inner_arr, key=sort_key_inner) for inner_arr in arr2 if inner_arr], key=sort_key_outer)

        assert arr1_sorted == arr2_sorted, "The two sorted array-of-array structures do not match."
