sol_sql:
CREATE OR REPLACE FUNCTION aliasTrigger() RETURNS TRIGGER AS $alias_table$
BEGIN
  INSERT INTO alias (zip_code, alias)
  VALUES (NEW.zip_code,
          CASE
            WHEN POSITION(' ' IN NEW.city) > 0 THEN SUBSTRING(NEW.city FROM 1 FOR POSITION(' ' IN NEW.city) - 1)
            ELSE NEW.city
          END);
  RETURN NEW;
END;
$alias_table$ LANGUAGE plpgsql;

