    def run_sql_and_get_explain_rows(sql_list):




        rows_output = []
        with conn.cursor() as cur:
            for sql in sql_list:
                cur.execute(sql)

                if sql.strip().upper().startswith("EXPLAIN"):
                    rows_output = cur.fetchall()
        return rows_output


    pred_explain_rows = run_sql_and_get_explain_rows(pred_sqls)
    pred_has_rows10 = any("rows=10" in str(row) for row in pred_explain_rows)

    assert pred_has_rows10, (
        "Expected to find 'rows=10' in the tested scenario's EXPLAIN output, but it was not found."
    )

    return 1

