CREATE FUNCTION pg_try_advisory_lock_with_timeout(key bigint) RETURNS boolean
        SET lock_timeout TO '1s'
        AS $$
        BEGIN
        PERFORM pg_advisory_lock(key);
        RETURN true;
        EXCEPTION
        WHEN lock_not_available OR deadlock_detected THEN
            RETURN false;
        END;
        $$
        LANGUAGE plpgsql;

