SELECT json_object_agg(abbreviation, groupedStates) AS states_by_abbreviation
FROM (
  SELECT T1.abbreviation,
         json_agg(
           json_build_object(
             'state_abbreviation', T1.abbreviation,
             'zip_codes', (
               SELECT json_agg(
                 json_build_object(
                   'zip_code', T2.zip_code,
                   'city', T2.city
                 )
               )
               FROM zip_data AS T2
               WHERE T2.state = T1.abbreviation
             ),
             'area_codes', (
               SELECT json_agg(
                 json_build_object(
                   'area_code', T3.area_code,
                   'zip_code_ref', T3.zip_code
                 )
               )
               FROM area_code AS T3 JOIN zip_data AS T4 ON T3.zip_code = T4.zip_code
               WHERE T4.state = T1.abbreviation
             )
           )
         ) AS groupedStates
  FROM state AS T1
  GROUP BY T1.abbreviation
) AS sub;

