SELECT json_object_agg(rating, groupedFilms) AS films_by_rating
FROM (
  SELECT T1.rating,
         json_agg(
           json_build_object(
             'film_id', T1.film_id,
             'actors', (
               SELECT json_agg(
                 json_build_object(
                   'actor_id', T3.actor_id,
                   'first_name', T3.first_name
                 )
               )
               FROM film_actor AS T2
               JOIN actor AS T3 ON T2.actor_id = T3.actor_id
               WHERE T2.film_id = T1.film_id
             ),
             'categories', (
               SELECT json_agg(
                 json_build_object(
                   'category_id', T5.category_id,
                   'name', T5.name
                 )
               )
               FROM film_category AS T4
               JOIN category AS T5 ON T4.category_id = T5.category_id
               WHERE T4.film_id = T1.film_id
             )
           )
         ) AS groupedFilms
  FROM film AS T1
  GROUP BY T1.rating
) AS sub;

