CREATE OR REPLACE FUNCTION FIND_ABBREV_COLUMN(
    IN_TYPE TEXT,
    IN_CODE TEXT,
    IN_REQUESTED_COLUMN TEXT
) RETURNS TEXT AS $$
DECLARE
    C_ABBREV REFCURSOR;
    C_ABBREV_REC RECORD;
    RESULT TEXT;
    query TEXT;
BEGIN
    query := 'SELECT * FROM abbrev WHERE Type = $1 AND Code = $2';

    OPEN C_ABBREV FOR EXECUTE query USING IN_TYPE, IN_CODE;

    LOOP
        FETCH C_ABBREV INTO C_ABBREV_REC;
        EXIT WHEN NOT FOUND;

        -- Incorrectly trying to access cursor directly instead of record
        IF IN_REQUESTED_COLUMN = 'TYPE' THEN
            RESULT := C_ABBREV.Type; 
            EXIT;
        ELSIF IN_REQUESTED_COLUMN = 'CODE' THEN
            RESULT := C_ABBREV.Code;
            EXIT;
        ELSIF IN_REQUESTED_COLUMN = 'FULLNAME' THEN
            RESULT := C_ABBREV.Fullname;
            EXIT;
        END IF;
    END LOOP;
    CLOSE C_ABBREV;
    RETURN RESULT;
END;
$$ LANGUAGE plpgsql;

