        WHERE zip_code = p_zip_code;
    ELSE
        INSERT INTO zip_data (zip_code, state_fips, city, time_zone)
        VALUES (p_zip_code, p_state_fips, p_city, p_time_zone);
    END IF;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION InsertOrUpdateCustomer(
    p_customer_id INTEGER,
    p_first_name TEXT,
    p_email TEXT,
    p_last_name TEXT
)
RETURNS VOID AS
$$
BEGIN
    IF EXISTS (SELECT 1 FROM customer WHERE customer_id = p_customer_id) THEN
        UPDATE customer
        SET email = p_email, last_name = p_last_name
        WHERE customer_id = p_customer_id;
    ELSE
        INSERT INTO customer (customer_id, first_name, email, last_name)
        VALUES (p_customer_id, p_first_name, p_email, p_last_name);
    END IF;
END;
$$ LANGUAGE plpgsql;

