WITH labeled_ends AS (SELECT lag(sa.ts) OVER (PARTITION BY sa.season_id, sa.duration ORDER BY sa.ts) = sa.ts - interval '5' minute IS NOT TRUE AS begins_period, sa.ts, lead(sa.ts) OVER (PARTITION BY sa.season_id, sa.duration ORDER BY sa.ts) = sa.ts + interval '5' minute IS NOT TRUE AS ends_period, sa.season_id, sa.duration FROM view_summary_temp sa),
periods AS (SELECT labeled_ends.ts, CASE WHEN labeled_ends.ends_period THEN labeled_ends.ts ELSE lead(labeled_ends.ts) OVER (PARTITION BY labeled_ends.season_id, labeled_ends.duration ORDER BY labeled_ends.ts) END AS period_end, labeled_ends.season_id, labeled_ends.duration, labeled_ends.begins_period FROM labeled_ends WHERE labeled_ends.begins_period OR labeled_ends.ends_period)
SELECT tstzrange(periods.ts, periods.period_end, '[]') AS valid_interval, periods.season_id, periods.duration FROM periods WHERE periods.begins_period ORDER BY periods.season_id, periods.duration, periods.ts;

