       SUM(total),
       COUNT(*)
FROM invoice
GROUP BY EXTRACT(YEAR
                 FROM invoice_date),
         TO_CHAR(invoice_date, 'IW')
ORDER BY EXTRACT(YEAR
                 FROM invoice_date),
         TO_CHAR(invoice_date, 'IW');
END $$;

DO $$
DECLARE
    v_track_name VARCHAR(512);
    v_album_title TEXT;
    v_artist_name VARCHAR(512);
    v_genre_name TEXT;
BEGIN
    SELECT "t"."name",
           "a"."title",
           "ar"."name",
           "g"."name"
    FROM "track" "t"
    INNER JOIN "album" "a" ON "t"."album_id" = "a"."album_id"
    INNER JOIN "artist" "ar" ON "a"."artist_id" = "ar"."artist_id"
    INNER JOIN "genre" "g" ON "t"."genre_id" = "g"."genre_id"
    ORDER BY "t"."name",
             "a"."title",
             "ar"."name";
END $$;

DO $$
DECLARE
    v_tv_show_id BIGINT;
    v_title VARCHAR(512);
    v_season_id BIGINT;
    v_season_number INTEGER;
    v_view_summary_id BIGINT;
    v_duration VARCHAR(512);
    v_hours_viewed INTEGER;
    v_views INTEGER;
BEGIN
    SELECT "t"."id",
           "t"."title",
           "s"."id",
           "s"."season_number",
           "v"."id",
           "v"."duration",
           "v"."hours_viewed",
           "v"."views"
    FROM "tv_show" "t"
    INNER JOIN "season" "s" ON "t"."id" = "s"."tv_show_id"
    INNER JOIN "view_summary" "v" ON "s"."id" = "v"."season_id"
    ORDER BY "t"."id",
             "s"."id",
             "v"."id";
END $$;

DO $$
DECLARE
    v_employee_id BIGINT;
    v_first_name VARCHAR(255);
    v_last_name VARCHAR(255);
    v_dept_name VARCHAR(255);
    v_salary_amount BIGINT;
    v_title VARCHAR(255);
BEGIN
    SELECT e.id,
           e.first_name,
           e.last_name,
           d.dept_name,
           s.amount,
           t.title
    FROM employee e
    INNER JOIN department_employee de ON e.id = de.employee_id
    INNER JOIN department d ON de.department_id = d.id
    INNER JOIN salary s ON e.id = s.employee_id
    INNER JOIN title t ON e.id = t.employee_id
    ORDER BY e.id,
             d.id,
             s.amount;
END $$;

DO $$
DECLARE
    v_flight_id INTEGER;
    v_aircraft_model JSONB;
    v_departure_airport_name JSONB;
    v_arrival_airport_name JSONB;
    v_ticket_no CHARACTER;
BEGIN
    SELECT "f"."flight_id",
           "ad"."model",
           "apd"."airport_name",
           "apa"."airport_name",
           "t"."ticket_no"
    FROM "flights" "f"
    INNER JOIN "aircrafts_data" "ad" ON "f"."aircraft_code" = "ad"."aircraft_code"
    INNER JOIN "airports_data" "apd" ON "f"."departure_airport" = "apd"."airport_code"
    INNER JOIN "airports_data" "apa" ON "f"."arrival_airport" = "apa"."airport_code"
    INNER JOIN "ticket_flights" "tf" ON "f"."flight_id" = "tf"."flight_id"
    INNER JOIN "tickets" "t" ON "tf"."ticket_no" = "t"."ticket_no"
    ORDER BY "f"."flight_id",
             "ad"."model",
             "t"."ticket_no";
END $$;

