CREATE OR REPLACE FUNCTION FIND_CUSTOMER_COLUMN(
    IN_FIRST_NAME VARCHAR,
    IN_LAST_NAME VARCHAR,
    IN_COMPANY VARCHAR,
    IN_ADDRESS VARCHAR,
    IN_REQUESTED_COLUMN VARCHAR
) RETURNS VARCHAR AS $$
DECLARE
    C_CUSTOMER REFCURSOR;
    C_CUSTOMER_REC RECORD;
    RESULT VARCHAR(255);
    query TEXT;
BEGIN
    query := 'SELECT * FROM customer WHERE first_name = $1 AND last_name = $2 AND company = $3';
    IF IN_ADDRESS IS NULL THEN
         query := query || ';';
         OPEN C_CUSTOMER FOR EXECUTE query USING IN_FIRST_NAME, IN_LAST_NAME, IN_COMPANY;
    ELSE
         query := query || ' AND address = $4;';
         OPEN C_CUSTOMER FOR EXECUTE query USING IN_FIRST_NAME, IN_LAST_NAME, IN_COMPANY, IN_ADDRESS;
    END IF;

    LOOP
        FETCH C_CUSTOMER INTO C_CUSTOMER_REC;
        EXIT WHEN NOT FOUND;

        IF IN_REQUESTED_COLUMN = 'FIRST_NAME' THEN
            RESULT := C_CUSTOMER.first_name;
            EXIT;
        ELSIF IN_REQUESTED_COLUMN = 'LAST_NAME' THEN
            RESULT := C_CUSTOMER.last_name;
            EXIT;
        ELSIF IN_REQUESTED_COLUMN = 'COMPANY' THEN
            RESULT := C_CUSTOMER.company;
            EXIT;
        END IF;
    END LOOP;
    CLOSE C_CUSTOMER;
    RETURN RESULT;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION FIND_TEST_TABLE_COLUMN(
    IN_COLUMN1 VARCHAR,
    IN_COLUMN2 VARCHAR,
    IN_COLUMN3 VARCHAR,
    IN_COLUMN4 VARCHAR,
    IN_REQUESTED_COLUMN VARCHAR
) RETURNS VARCHAR AS $$
DECLARE
    C_TEST_TABLE REFCURSOR;
    C_TEST_TABLE_REC RECORD;
    RESULT VARCHAR(255);
    query TEXT;
BEGIN
    query := 'SELECT * FROM test_table WHERE column1 = $1 AND column2 = $2 AND column3 = $3';
    IF IN_COLUMN4 IS NULL THEN
         query := query || ';';
         OPEN C_TEST_TABLE FOR EXECUTE query USING IN_COLUMN1, IN_COLUMN2, IN_COLUMN3;
    ELSE
         query := query || ' AND column4 = $4;';
         OPEN C_TEST_TABLE FOR EXECUTE query USING IN_COLUMN1, IN_COLUMN2, IN_COLUMN3, IN_COLUMN4;
    END IF;

    LOOP
        FETCH C_TEST_TABLE INTO C_TEST_TABLE_REC;
        EXIT WHEN NOT FOUND;

        IF IN_REQUESTED_COLUMN = 'COLUMN1' THEN
            RESULT := C_TEST_TABLE.column1;
            EXIT;
        ELSIF IN_REQUESTED_COLUMN = 'COLUMN2' THEN
            RESULT := C_TEST_TABLE.column2;
            EXIT;
        ELSIF IN_REQUESTED_COLUMN = 'COLUMN3' THEN
            RESULT := C_TEST_TABLE.column3;
            EXIT;
        END IF;
    END LOOP;
    CLOSE C_TEST_TABLE;
    RETURN RESULT;
END;
$$ LANGUAGE plpgsql;

