CREATE OR REPLACE FUNCTION InsertOrUpdateLegoSets(
    p_set_num VARCHAR,
    p_name VARCHAR,
    p_year INTEGER,
    p_theme_id INTEGER,
    p_num_parts INTEGER
)
RETURNS VOID AS
$$
BEGIN
    IF EXISTS (SELECT 1 FROM lego_sets WHERE set_num = p_set_num) THEN
        UPDATE lego_sets
        SET name = p_name, year = p_year
        WHERE set_num = p_set_num;
    ELSE
        INSERT INTO lego_sets (set_num, name, year, theme_id, num_parts)
        VALUES (p_set_num, p_name, p_year, p_theme_id, p_num_parts);
    END IF;
END;
$$ LANGUAGE plpgsql;

